import { useCallback, useEffect, useState } from "react";
import {
  Activity as ActivityIcon,
  Archive,
  Bot,
  History,
  Plug,
  Play,
  RotateCcw,
  Square,
  Trash2,
} from "lucide-react";
// @ts-ignore wailsjs bindings are generated by wails build
import {
  AgentActivity,
  AgentProviders,
  AgentSessions,
  ArchiveAgent,
  DeleteAgent,
  HookStatus,
  InstallAgentHooks,
  LaunchAgent,
  RemoveAgentHooks,
  RenameAgent,
  ResumeAgent,
  StopAgent,
} from "../../wailsjs/go/controllers/Agents";
// @ts-ignore wailsjs bindings are generated by wails build
import { ListProjects } from "../../wailsjs/go/controllers/Projects";
// @ts-ignore wailsjs bindings are generated by wails build
import { EventsOn } from "../../wailsjs/runtime";
import { useDialogs } from "../components/dialogs/DialogProvider";
import { useT } from "../lib/i18n";

type Provider = { kind: string; label: string };
type Installed = { provider: Provider; path: string; version: string };
type HookState = { provider: string; label: string; supported: boolean; installed: boolean };
type Session = {
  id: string;
  provider: string;
  project?: string;
  dir: string;
  ptyId?: string;
  providerSession?: string;
  title?: string;
  startedAt: string;
  archived?: boolean;
};
type Activity = {
  time: string;
  provider: string;
  event: string;
  sessionId?: string;
  kitodockId?: string;
  summary?: string;
};

// The agents page: provider launcher, session list with resume/archive,
// hook toggles and the live activity feed.
export default function Agents() {
  const t = useT();
  const dialogs = useDialogs();
  const [providers, setProviders] = useState<Installed[]>([]);
  const [hooks, setHooks] = useState<HookState[]>([]);
  const [sessions, setSessions] = useState<Session[]>([]);
  const [activity, setActivity] = useState<Activity[]>([]);
  const [projects, setProjects] = useState<string[]>([]);
  const [launchProject, setLaunchProject] = useState("");
  const [showArchived, setShowArchived] = useState(false);

  const refresh = useCallback(() => {
    AgentProviders().then((list: Installed[]) => setProviders(list ?? [])).catch(() => {});
    HookStatus().then((list: HookState[]) => setHooks(list ?? [])).catch(() => {});
    AgentSessions(showArchived).then((list: Session[]) => setSessions(list ?? [])).catch(() => {});
    AgentActivity(50).then((list: Activity[]) => setActivity(list ?? [])).catch(() => {});
  }, [showArchived]);

  useEffect(() => {
    ListProjects()
      .then((list: Array<{ name: string }>) => {
        const names = (list ?? []).map((p) => p.name);
        setProjects(names);
        if (names.length > 0) setLaunchProject(names[0]);
      })
      .catch(() => {});
    refresh();
    // @ts-ignore EventsOn returns a cancel function
    const c1 = EventsOn("agents:activity", (p: { events: Activity[] }) => {
      setActivity((prev) => [...(p.events ?? []), ...prev].slice(0, 100));
    });
    // @ts-ignore EventsOn returns a cancel function
    const c2 = EventsOn("agents:session", () => refresh());
    return () => {
      c1?.();
      c2?.();
    };
  }, [refresh]);

  const launch = async (kind: string) => {
    if (!launchProject) {
      await dialogs.alert({ title: t("agents.title"), message: t("agents.needProject") });
      return;
    }
    try {
      await LaunchAgent(kind, launchProject, "");
      refresh();
    } catch (error) {
      await dialogs.alert({ title: kind, message: String(error) });
    }
  };

  const resume = async (session: Session) => {
    try {
      await ResumeAgent(session.id);
      refresh();
    } catch (error) {
      await dialogs.alert({ title: session.title || session.id, message: String(error) });
    }
  };

  const stop = async (session: Session) => {
    await StopAgent(session.id);
    refresh();
  };

  const rename = async (session: Session) => {
    const title = window.prompt(t("agents.renameTo"), session.title || "");
    if (!title || title === session.title) return;
    await RenameAgent(session.id, title);
    refresh();
  };

  const archive = async (session: Session) => {
    await ArchiveAgent(session.id, !session.archived);
    refresh();
  };

  const remove = async (session: Session) => {
    const yes = await dialogs.confirm({
      title: t("agents.deleteConfirm", { name: session.title || session.id }),
      danger: true,
    });
    if (!yes) return;
    await DeleteAgent(session.id);
    refresh();
  };

  const toggleHook = async (hook: HookState) => {
    try {
      if (hook.installed) await RemoveAgentHooks(hook.provider);
      else await InstallAgentHooks(hook.provider);
      refresh();
    } catch (error) {
      await dialogs.alert({ title: hook.label, message: String(error) });
    }
  };

  const running = (session: Session) => session.ptyId !== "";

  return (
    <div className="flex h-full min-h-0 flex-col">
      <header className="flex items-center justify-between">
        <h1 className="text-lg font-semibold text-white/95">{t("agents.title")}</h1>
        {projects.length > 0 && (
          <select
            className="input py-1 text-xs"
            value={launchProject}
            onChange={(e) => setLaunchProject(e.target.value)}
            aria-label="Project"
          >
            {projects.map((name) => (
              <option key={name} value={name}>
                {name}
              </option>
            ))}
          </select>
        )}
      </header>

      <div className="mt-3 min-h-0 flex-1 space-y-3 overflow-y-auto pr-0.5">
        {/* Launcher */}
        <section className="glass p-3">
          <p className="mb-2 text-[11px] uppercase tracking-wide text-white/40">
            {t("agents.launcher")}
          </p>
          <div className="flex flex-wrap gap-2">
            {providers.map((p) => (
              <button
                key={p.provider.kind}
                type="button"
                disabled={!p.path}
                title={p.path ? p.version || t("agents.installed") : t("agents.notInstalled")}
                onClick={() => void launch(p.provider.kind)}
                className={`flex items-center gap-1.5 rounded-md border px-3 py-1.5 text-xs font-medium ${
                  p.path
                    ? "border-accent/40 bg-accent/15 text-white hover:bg-accent/25"
                    : "border-white/10 bg-white/5 text-white/30"
                }`}
              >
                <Play className="h-3 w-3" /> {p.provider.label}
              </button>
            ))}
          </div>
        </section>

        {/* Hooks */}
        <section className="glass p-3">
          <p className="mb-2 flex items-center gap-1.5 text-[11px] uppercase tracking-wide text-white/40">
            <Plug className="h-3 w-3" /> {t("agents.hooks")}
          </p>
          <div className="space-y-1.5">
            {hooks.map((hook) => (
              <div key={hook.provider} className="flex items-center gap-2 text-xs">
                <span className="w-28 shrink-0 text-white/70">{hook.label}</span>
                {hook.supported ? (
                  <button
                    type="button"
                    onClick={() => void toggleHook(hook)}
                    className={`rounded border px-2 py-0.5 text-[10px] ${
                      hook.installed
                        ? "border-emerald-400/40 bg-emerald-500/10 text-emerald-300 hover:bg-emerald-500/20"
                        : "border-white/15 bg-white/5 text-white/50 hover:bg-white/10"
                    }`}
                  >
                    {hook.installed ? t("agents.hooksOn") : t("agents.hooksOff")}
                  </button>
                ) : (
                  <span className="text-[10px] text-white/30">{t("agents.hooksUnsupported")}</span>
                )}
              </div>
            ))}
          </div>
        </section>

        {/* Sessions */}
        <section className="glass p-3">
          <div className="mb-2 flex items-center justify-between">
            <p className="flex items-center gap-1.5 text-[11px] uppercase tracking-wide text-white/40">
              <Bot className="h-3 w-3" /> {t("agents.sessions")}
            </p>
            <button
              type="button"
              onClick={() => setShowArchived((v) => !v)}
              className="text-[10px] text-white/40 hover:text-white/70"
            >
              {showArchived ? t("agents.hideArchived") : t("agents.showArchived")}
            </button>
          </div>
          {sessions.length === 0 ? (
            <p className="py-4 text-center text-sm text-white/40">{t("agents.empty")}</p>
          ) : (
            <div className="space-y-1.5">
              {sessions.map((session) => (
                <div
                  key={session.id}
                  className={`flex items-center gap-2 rounded border px-2 py-1.5 ${
                    session.archived ? "border-white/5 opacity-50" : "border-white/10"
                  }`}
                >
                  <span
                    className={`h-1.5 w-1.5 shrink-0 rounded-full ${
                      running(session) ? "bg-emerald-400" : "bg-white/20"
                    }`}
                  />
                  <div className="min-w-0 flex-1">
                    <div className="flex items-center gap-1.5">
                      <span className="truncate text-xs font-medium text-white/85">
                        {session.title || session.id}
                      </span>
                      <span className="shrink-0 rounded border border-white/10 px-1 text-[9px] text-white/40">
                        {session.provider}
                      </span>
                    </div>
                    <p className="truncate font-mono text-[10px] text-white/30">
                      {session.project || session.dir} · {new Date(session.startedAt).toLocaleString()}
                    </p>
                  </div>
                  <div className="flex shrink-0 gap-1">
                    {running(session) ? (
                      <button
                        type="button"
                        onClick={() => void stop(session)}
                        title={t("agents.stop")}
                        className="rounded border border-red-400/30 bg-red-500/10 p-1 text-red-300 hover:bg-red-500/20"
                      >
                        <Square className="h-3 w-3" />
                      </button>
                    ) : (
                      <button
                        type="button"
                        disabled={!session.providerSession}
                        title={session.providerSession ? t("agents.resume") : t("agents.noResume")}
                        onClick={() => void resume(session)}
                        className="rounded border border-white/10 bg-white/5 p-1 text-white/60 hover:bg-white/10 hover:text-white disabled:opacity-30"
                      >
                        <RotateCcw className="h-3 w-3" />
                      </button>
                    )}
                    <button
                      type="button"
                      onClick={() => void rename(session)}
                      title={t("agents.rename")}
                      className="rounded border border-white/10 bg-white/5 p-1 text-white/60 hover:bg-white/10 hover:text-white"
                    >
                      <History className="h-3 w-3" />
                    </button>
                    <button
                      type="button"
                      onClick={() => void archive(session)}
                      title={session.archived ? t("agents.unarchive") : t("agents.archive")}
                      className="rounded border border-white/10 bg-white/5 p-1 text-white/60 hover:bg-white/10 hover:text-white"
                    >
                      <Archive className="h-3 w-3" />
                    </button>
                    <button
                      type="button"
                      onClick={() => void remove(session)}
                      title={t("agents.delete")}
                      className="rounded border border-red-400/30 bg-red-500/10 p-1 text-red-300 hover:bg-red-500/20"
                    >
                      <Trash2 className="h-3 w-3" />
                    </button>
                  </div>
                </div>
              ))}
            </div>
          )}
        </section>

        {/* Activity */}
        <section className="glass p-3">
          <p className="mb-2 flex items-center gap-1.5 text-[11px] uppercase tracking-wide text-white/40">
            <ActivityIcon className="h-3 w-3" /> {t("agents.activity")}
          </p>
          {activity.length === 0 ? (
            <p className="py-3 text-center text-xs text-white/30">{t("agents.activityEmpty")}</p>
          ) : (
            <div className="max-h-56 space-y-0.5 overflow-y-auto">
              {activity.map((entry, i) => (
                <div key={i} className="flex items-baseline gap-2 font-mono text-[10px]">
                  <span className="shrink-0 text-white/25">
                    {new Date(entry.time).toLocaleTimeString()}
                  </span>
                  <span className="w-14 shrink-0 text-accent2/80">{entry.provider}</span>
                  <span className="w-24 shrink-0 text-white/40">{entry.event}</span>
                  <span className="min-w-0 flex-1 truncate text-white/60">
                    {entry.summary || entry.kitodockId || entry.sessionId || ""}
                  </span>
                </div>
              ))}
            </div>
          )}
        </section>
      </div>
    </div>
  );
}
